shader_type canvas_item;

uniform float hit_amount : hint_range(0.0, 1.0) = 0.0;
uniform vec4 flash_color : source_color = vec4(1.0, 0.0, 0.0, 1.0);
uniform float flash_strength : hint_range(0.0, 1.0) = 0.6;

void fragment() {
	COLOR.rgb = mix(COLOR.rgb, flash_color.rgb, hit_amount * flash_strength);
}

shader_type spatial;
render_mode unshaded;

uniform sampler2D tex_srgb : source_color, filter_nearest;
uniform sampler2D tex_raw : filter_nearest;
uniform bool use_srgb = true;

void fragment() {
	if (use_srgb) {
		ALBEDO = texture(tex_srgb, UV).rgb;
	} else {
		ALBEDO = texture(tex_raw, UV).rgb;
	}
}

shader_type spatial;

group_uniforms colour;
uniform sampler2D albedo_tex : source_color, filter_linear_mipmap, repeat_enable;
uniform vec4 albedo_tint : source_color = vec4(1.0, 1.0, 1.0, 1.0);
uniform float brightness : hint_range(0.0, 2.0) = 1.0;

group_uniforms surface;
uniform sampler2D roughness_tex : filter_linear_mipmap, repeat_enable;
uniform float roughness_scale : hint_range(0.0, 1.0) = 1.0;
uniform float uv_scale : hint_range(0.1, 4.0) = 0.5;
